using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    // The default resolver so common types get metadata automatically.
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ── 1. Strongly-typed retrieval: GetTypeInfo<T>() ──────────────────
// Returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Type handled : {personInfo.Type.Name}");
Console.WriteLine($"Kind         : {personInfo.Kind}");
Console.WriteLine($"Properties   : {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");

// Round-trip to prove the metadata works.
var person = new Person("Alice", 30);
string json = JsonSerializer.Serialize(person, personInfo);
Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Round-trip    : {json} → {deserialized}");

Console.WriteLine();

// ── 2. Probe without throwing: TryGetTypeInfo() ────────────────────
// Available since .NET 9.  Returns false instead of throwing when the
// resolver can't produce metadata for the requested type.

// Use a *source-gen-only* context that knows about Person but NOT int[].
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = PersonOnlyContext.Default
};

bool havePerson = limitedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? pInfo);
bool haveArray  = limitedOptions.TryGetTypeInfo(typeof(int[]),  out JsonTypeInfo? aInfo);

Console.WriteLine($"Person metadata available? {havePerson} (info: {pInfo?.Type.Name ?? "null"})");
Console.WriteLine($"int[]  metadata available? {haveArray}  (info: {aInfo?.Type.Name ?? "null"})");

// ── Types ──────────────────────────────────────────────────────────
public record Person(string Name, int Age);

// A source-generated context that *only* knows about Person.
[JsonSerializable(typeof(Person))]
public partial class PersonOnlyContext : JsonSerializerContext;

